// Set CREATED_BY after import (Auth0 subject).
// Maps ALL Find results in one run — no Split In Batches needed (avoids loop/done wiring issues).
const CREATED_BY = 'auth0|REPLACE_WITH_YOUR_AUTH0_SUBJECT';
const now = new Date().toISOString();

// Coerce MongoDB _id to a 24-char hex string. n8n's MongoDB update node calls
// `new ObjectId(item._id)` which silently no-ops if _id arrives as an object
// after the Find → CodeNode sandbox boundary — symptom: data.status stays 'pending'.
function toHexId(v) {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  if (typeof v.toHexString === 'function') return v.toHexString();
  if (typeof v.toString === 'function') {
    const s = v.toString();
    if (/^[a-f0-9]{24}$/i.test(s)) return s;
  }
  if (v.$oid && typeof v.$oid === 'string') return v.$oid;
  const buf = v.buffer ?? v.id ?? v;
  if (buf && (Array.isArray(buf) || (typeof buf.length === 'number' && typeof buf[0] === 'number') || buf.data)) {
    const arr = buf.data || buf;
    if (arr && typeof arr.length === 'number') {
      const bytes = [];
      for (let i = 0; i < arr.length; i++) bytes.push(Number(arr[i]).toString(16).padStart(2, '0'));
      const hex = bytes.join('');
      if (/^[a-f0-9]{24}$/i.test(hex)) return hex;
    }
  }
  return String(v);
}

return items.map(({ json: doc }) => {
  const d = doc.data || {};
  const dateVal = d.date ? new Date(d.date) : new Date(doc.createdAt || now);
  const idHex = toHexId(doc._id);
  if (!idHex || !/^[a-f0-9]{24}$/i.test(idHex)) {
    console.warn('Prepare: doc._id is not a valid hex ObjectId; update will likely no-op.', doc._id);
  }
  return {
    json: {
      _id: idHex,
      'data.status': 'active',
      jobId: d.jobId,
      jobUrl: d.jobUrl ?? '',
      jobTitle: d.jobTitle ?? '',
      companyName: d.companyName ?? '',
      jobDescription: d.jobDescription ?? '',
      jobCategory: d.jobCategory ?? '',
      date: dateVal.toISOString(),
      createdBy: CREATED_BY,
      job_creation_type: 'automation',
      status: 'active',
      isFlagged: Boolean(d.isFlagged),
      jobExperience: typeof d.jobExperience === 'number' ? d.jobExperience : 0,
      __v: 0,
      createdAt: now,
      updatedAt: now,
    },
  };
});

// Run-once-for-each-item + $('Prepare').all() only sees paired items (~1 row) — use run-once-for-all.
const prepared = $('Prepare update + job row').all();
if (prepared.length !== items.length) {
  throw new Error(`Shape: Prepare has ${prepared.length} items but Update passed ${items.length}`);
}
function pickJob(p) {
  return {
    jobId: p.jobId,
    jobUrl: p.jobUrl,
    jobTitle: p.jobTitle,
    companyName: p.companyName,
    jobDescription: p.jobDescription,
    jobCategory: p.jobCategory,
    date: p.date,
    createdBy: p.createdBy,
    job_creation_type: p.job_creation_type,
    status: p.status,
    isFlagged: p.isFlagged,
    jobExperience: p.jobExperience,
    __v: p.__v,
    createdAt: p.createdAt,
    updatedAt: p.updatedAt,
  };
}
return prepared.map(({ json: p }) => ({ json: pickJob(p) }));
